CREATE TABLE IF NOT EXISTS LibraryHeads (Kind VARCHAR(32) NOT NULL, Id VARCHAR(100) NOT NULL, Name VARCHAR(255) NOT NULL, Revision BIGINT NOT NULL, VersionId VARCHAR(100) NOT NULL, UpdatedAt VARCHAR(40) NOT NULL, PRIMARY KEY(Kind,Id));
CREATE TABLE IF NOT EXISTS LibraryVersions (Id VARCHAR(100) PRIMARY KEY, Kind VARCHAR(32) NOT NULL, DocumentId VARCHAR(100) NOT NULL, Content LONGTEXT NOT NULL, CreatedAt VARCHAR(40) NOT NULL, INDEX(Kind,DocumentId));
CREATE TABLE IF NOT EXISTS LibraryReferences (OwnerType VARCHAR(10) NOT NULL, OwnerId VARCHAR(100) NOT NULL, Kind VARCHAR(32) NOT NULL, LibraryId VARCHAR(100) NOT NULL, VersionId VARCHAR(100) NOT NULL, PRIMARY KEY(OwnerType,OwnerId,Kind,LibraryId,VersionId), INDEX(Kind,LibraryId));
